package main
import("bytes";"encoding/binary";"encoding/json";"fmt";"os";"path/filepath";"runtime";"strconv";"syscall";"time";native "github.com/authenticity-labs/pill-packer/go")
func cpu()(float64,int64){var r syscall.Rusage;syscall.Getrusage(syscall.RUSAGE_SELF,&r);return float64(r.Utime.Sec+r.Stime.Sec)+float64(r.Utime.Usec+r.Stime.Usec)/1e6,r.Maxrss}
func main(){runtime.GOMAXPROCS(1);dir:=os.Args[1];level,_:=strconv.Atoi(os.Args[2]);op:=os.Args[3];paths,_:=filepath.Glob(filepath.Join(dir,"*.pac"));var raws,packed [][]byte;rawBytes,stored,records:=0,0,0
 for _,p:=range paths{raw,e:=os.ReadFile(p);if e!=nil{panic(e)};name:=p+fmt.Sprintf(".rust-owned-zstd-%d",level);if op=="prepare"{enc,e:=native.SealOwned(raw,514,level,false);if e!=nil{panic(e)};if e=os.WriteFile(name,enc.Bytes(),0644);e!=nil{panic(e)};enc.Close()};enc,e:=os.ReadFile(name);if e!=nil{panic(e)};raws=append(raws,raw);packed=append(packed,enc);rawBytes+=len(raw);stored+=len(enc);records+=int(binary.LittleEndian.Uint32(raw[12:16]))};if op=="prepare"{return}
 work:=func(verify bool){for i,raw:=range raws{var out *native.OwnedBytes;var err error;if op=="encode"{out,err=native.SealOwned(raw,514,level,false);if verify&&!bytes.Equal(out.Bytes(),packed[i]){panic("encode mismatch")}}else{out,err=native.ExpandOwned(packed[i]);if verify&&!bytes.Equal(out.Bytes(),raw){panic("decode mismatch")}};if err!=nil{panic(err)};runtime.KeepAlive(out.Bytes());out.Close()}}
 work(true);runtime.GC();var before,after runtime.MemStats;runtime.ReadMemStats(&before);c,_:=cpu();start:=time.Now();n:=0;for{work(false);n++;if time.Since(start)>=200*time.Millisecond{break}};wall:=time.Since(start);end,rss:=cpu();runtime.ReadMemStats(&after)
 json.NewEncoder(os.Stdout).Encode(map[string]any{"dataset":filepath.Base(dir),"implementation":"rust-owned","codec":"zstd","level":level,"operation":op,"packs":len(raws),"records":records,"raw_bytes":rawBytes,"stored_bytes":stored,"loops":n,"wall_ms":float64(wall.Nanoseconds())/1e6/float64(n),"cpu_ms":(end-c)*1000/float64(n),"peak_rss_bytes":rss,"allocated_bytes_per_pass":float64(after.TotalAlloc-before.TotalAlloc)/float64(n),"gc_cycles":after.NumGC-before.NumGC})
}
